# ============================================================
# SERVER
# ============================================================

server &lt;- function(
  input,
  output,
  session
) {


  # ==========================================================
  # AVAILABLE SUBDISCIPLINES
  # ==========================================================

  available_subfields &lt;- reactive({


    d &lt;- coords[
      coords$type == "subfield",
    ]


    if (
      is.null(input$field_filter) ||
      input$field_filter == "All"
    ) {

      return(
        d$label
      )

    }


    d$label[
      d$stem == input$field_filter
    ]

  })



  # ==========================================================
  # UPDATE SELECTOR WHEN STEM FILTER CHANGES
  # ==========================================================

  observeEvent(

    input$field_filter,

    {


      choices &lt;-
        available_subfields()


      current &lt;-
        input$subfields


      if (
        is.null(current)
      ) {

        current &lt;-
          character(0)

      }


      current &lt;-
        intersect(
          current,
          choices
        )


      updateSelectizeInput(

        session,

        "subfields",

        choices = choices,

        selected = current,

        server = FALSE

      )

    }

  )



  # ==========================================================
  # CLEAR SELECTED SUBDISCIPLINES
  # ==========================================================

  observeEvent(

    input$clear_subfields,

    {

      updateSelectizeInput(

        session,

        "subfields",

        choices =
          available_subfields(),

        selected =
          character(0),

        server = FALSE

      )

    }

  )



  # ==========================================================
  # FACTORIAL SPACE
  # ==========================================================

  output$space &lt;- renderUI({


    layers &lt;-
      input$layers


    if (
      is.null(layers)
    ) {

      layers &lt;-
        character(0)

    }



    # --------------------------------------------------------
    # Plot limits
    #
    # If active variables are displayed, use the complete
    # factorial space. Otherwise zoom into the area containing
    # clusters and subdisciplines.
    # --------------------------------------------------------

    if (
      "variables" %in% layers
    ) {

      xmin &lt;- -0.80
      xmax &lt;-  2.25

      ymin &lt;- -2.20
      ymax &lt;-  0.80

    } else {

      xmin &lt;- -0.70
      xmax &lt;-  1.20

      ymin &lt;- -0.70
      ymax &lt;-  0.75

    }



    # --------------------------------------------------------
    # SVG dimensions
    # --------------------------------------------------------

    svg_width  &lt;- 1000
    svg_height &lt;- 560

    left   &lt;- 85
    right  &lt;- 965

    top    &lt;- 38
    bottom &lt;- 485



    # --------------------------------------------------------
    # Coordinate transforms
    # --------------------------------------------------------

    sx &lt;- function(x) {

      left +
        (x - xmin) /
        (xmax - xmin) *
        (right - left)

    }


    sy &lt;- function(y) {

      bottom -
        (y - ymin) /
        (ymax - ymin) *
        (bottom - top)

    }



    esc &lt;- function(x) {

      as.character(
        htmltools::htmlEscape(
          x
        )
      )

    }



    # ========================================================
    # AXES
    # ========================================================

    axis_html &lt;- ""


    if (
      xmin &lt;= 0 &&
      xmax &gt;= 0
    ) {

      axis_html &lt;- paste0(

        axis_html,

        '&lt;line
           x1="', sx(0), '"
           y1="', top, '"
           x2="', sx(0), '"
           y2="', bottom, '"
           stroke="#cccccc"
           stroke-width="1"/&gt;'

      )

    }


    if (
      ymin &lt;= 0 &&
      ymax &gt;= 0
    ) {

      axis_html &lt;- paste0(

        axis_html,

        '&lt;line
           x1="', left, '"
           y1="', sy(0), '"
           x2="', right, '"
           y2="', sy(0), '"
           stroke="#cccccc"
           stroke-width="1"/&gt;'

      )

    }



    # ========================================================
    # CLUSTERS
    # Drawn behind the other layers
    # ========================================================

    cluster_html &lt;- ""


    if (
      "clusters" %in% layers
    ) {


      # Larger clusters first, smaller ones afterwards

      ord &lt;-
        order(
          clusters$share,
          decreasing = TRUE
        )


      cluster_html &lt;- paste(

        vapply(

          ord,

          function(i) {


            px &lt;-
              sx(
                clusters$dim1[i]
              )


            py &lt;-
              sy(
                clusters$dim2[i]
              )


            # Radius proportional to cluster share

            radius &lt;-
              clusters$share[i] *
              0.80


            col &lt;-
              cluster_cols[
                clusters$gender[i]
              ]


            label_x &lt;-
              px +
              clusters$label_dx[i]


            label_y &lt;-
              py +
              clusters$label_dy[i]


            tooltip &lt;- paste0(

              clusters$cluster[i],

              " · ",
              sprintf(
                "%.1f%%",
                clusters$share[i]
              ),

              " · ",
              clusters$gender[i],

