          ),

          " · Dim 2 = ",
          sprintf(
            "%.3f",
            d$dim2[i]
          )

        )

      },

      character(1)

    )


    div(

      class =
        "selection-note",

      HTML(
        paste(
          lines,
          collapse = "&lt;br&gt;"
        )
      )

    )

  })

}



